steps.script:
# The failure is on screen WITH its dice, and the offer is on the same card.
var d = tree.root.get_node("BattleShockSequenceDialog")
var verdict = d.get_node("Content/VerdictLabel").get_parsed_text()
var ph = PhaseManager.get_current_phase_instance()
return [
	verdict.contains("FAILED"),
	d.get_node_or_null("Content/ButtonBar/CommandRerollButton") != null,
	d.get_node_or_null("Content/ButtonBar/KeepRollButton") != null,
	d.get_node("Content/DiceRow/TotalLabel").text.begins_with("= "),
	ph._awaiting_reroll_decision,
	# No second dialog stacked on top of the card.
	tree.root.get_node_or_null("CommandRerollDialog") == null
]

var d = tree.root.get_node("BattleShockSequenceDialog")
var summary = d.get_node("Content/VerdictLabel").get_parsed_text()
return [d.get_node("Content/HeadingLabel").text, summary.contains("Battle-shocked:") and summary.contains("Kommandos")]
